  int suffixLength = suffix.length();
  if(suffixLength == 0){
    return true;
  }
  int strLength = str.length();
  int suffixIndex = strLength - suffixLength;
  if(suffixIndex < 0){
    return false;
  }
  if(ignoreCase){
    //Case insensitive compare
    return str.substring(suffixIndex,strLength).equalsIgnoreCase(suffix);
  } else{
    //Case sensitive compare
    return str.substring(suffixIndex,strLength).equals(suffix);
  }
}

