public static boolean startsWith(String str, String prefix, boolean ignoreCase) {
    if (str == null || prefix == null) {
        return str == prefix;
    }
    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    }
    return str.startsWith(prefix);
}

