    //Validate parameters
    if(str == null || prefix == null){
        throw new NullPointerException("The input String and prefix must not be null");
    }

    //Check if the prefix is empty
    if(prefix.isEmpty()){
        return str.isEmpty();
    }

    //Check if the strings are equal (either case or case-insensitive)
    if(str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length())){
        return true;
    }

    //Check if the string starts with the prefix (case-sensitive)
    if(str.startsWith(prefix)){
