        }
        boolean isDir = file.isDirectory();
        // Check if file exists and if it is a directory
        if (file.exists() && isDir) {
            // Delete all sub-directories
            file.listFiles().forEach(File::delete);
        }
        // Check if file exists and if it is a file
        if (file.exists() && !isDir) {
            // Delete file
