public static String[] copyStrings(String[] src) {
    String[] dst = new String[src.length];
    for (int i = 0; i < src.length; i++) {
        dst[i] = src[i].toLowerCase();
    }
    return dst;
}

private static String[] copyStrings(final String[] src){
    String[] dst = new String[src.length];
    for(int i = 0; i < src.length; i++){
        dst[i] = src[i].toLowerCase();
    }
    return dst;
}

// Copy the input array and make all strings lower-case
String[] dst = new String[src.length];
for (int i = 0; i < src.length; i++) {
    dst[i] = src[i].toLowerCase();
}
return dst;

// OR
return src.clone();
}

public static String[] copyStrings(String[] src) {
    // Create a new array and initialize it with a copy of the src array
    String[] dst = new String[src.length];
    System.arraycopy(src, 0, dst, 0, src.length);

    // Iterate over the new array and convert all the strings to lower-case
    for (int i = 0; i < dst.length; i++) {
        dst[i] = dst[i].toLowerCase();
    }

    return dst;
}

private static String[] copyStrings(final String[] src){
    String[] dst = new String[src.length];
    for(int i = 0; i < src.length; i++){
        dst[i] = src[i].toLowerCase();
    }
    return dst;
}

