public static Character convertToCharacter(final Class<?> type, final Object value) throws Exception {
        if (type.isAssignableFrom(value.getClass())) {
            return (Character) value;
        }

        if (value instanceof String) {
            if (((String) value).length() != 1) {
                // Invalid input - not a single character
                throw new Exception("Invalid input. Expected a single character, got a string with length " + ((String) value).length());
            }

            return ((String) value).charAt(0);
        }

        if (value instanceof Number) {
            // Convert from number to char
            return (char) ((Number) value).intValue();
        }

        // Invalid input type, cannot be converted to Character
        throw new Exception("Cannot convert input type " + value.getClass() + " to Character");
    }

