    if (type.equals(Character.class) && value instanceof Character) {
        return (Character) value;
    }

    if (type.equals(Character.class) && value instanceof String) {
        if (((String) value).length() == 1) {
            return ((String) value).charAt(0);
        }

        throw new IllegalArgumentException("Cannot convert a string with multiple characters to a Character.");
