    if (type.equals(char.class) && value instanceof Character) {
        return (char) value;
    }

    if (type.equals(char.class) && value instanceof String) {
        if (((String) value).length() == 1) {
            return ((String) value).charAt(0);
        }

        throw new IllegalArgumentException("Cannot convert a string with multiple characters to a char.");
    }

    throw new Exception("Cannot convert an object of type " + value.getClass().getName() + " to a Character or char.");
}

