}

private int parseEndOfLine(String headerPart, int end) {
    // Check if we are already at the end of the line
    if (end == headerPart.length()) {
        return end;
    }

    // We are not at the end of the line, so find the next \r\n sequence
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
            return i + 1;
        }
    }

    // If no \r\n sequence was found, return the end of the string
    return headerPart.length();
}

