    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    // Find the index of the first CR (carriage return) character
    int crIndex = headerPart.indexOf('\r', end);

    // If there is no CR character, return the length of the string
    if (crIndex == -1) {
        return headerPart.length();
    }

    // If the CR character is followed by an LF character (line feed),
    // then it's a CRLF line ending
    if (crIndex < headerPart.length() - 1 && headerPart.charAt(crIndex + 1) == '\n') {
        return crIndex + 2;
    }

    // Otherwise, it's just a CR line ending
    return crIndex + 1;
}

