private String parseToken(char[] terminators) {
    StringBuilder token = new StringBuilder();
    boolean terminated = false;

    while (!terminated) {
        char c = (char) reader.read();
        if (c == -1) {
            terminated = true;
        } else {
            for (char terminator : terminators) {
                if (terminator == c) {
                    terminated = true;
                    break;
                } else {
                    token.append(c);
                }
            }
        }
    }

    return token.toString();
}

